FILES_TO_BACKUP = list(PAYLOAD.keys()) + ["data/phocap.db"]


def read_text(rel: str) -> str:
    path = PROJECT / rel
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {path}")
    return path.read_text(encoding="utf-8-sig")


def backup_files() -> list[dict]:
    manifest = []
    BACKUP.mkdir(parents=True, exist_ok=False)
    for rel in FILES_TO_BACKUP:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    MANIFEST.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return manifest


def restore_files(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def verify_base() -> None:
    # Cho phép cài lại B13B-6; nếu chưa có thì bắt buộc đúng nền B13B-5.
    router_now = PROJECT / "app" / "routers" / "report_inputs.py"
    if router_now.exists():
        router_text = router_now.read_text(encoding="utf-8-sig")
        if "BAI_13B_6_V1_STRUCTURED_INPUT_START" in router_text:
            return

    for rel, markers in EXPECTED_BASE_MARKERS.items():
        text = read_text(rel)
        for marker in markers:
            if marker not in text:
                raise RuntimeError(
                    f"Không tìm thấy nền Bài 13B-5 V1 trong {rel}: {marker}. "
                    "Dừng cài để không làm ảnh hưởng mã nguồn hiện tại."
                )


def write_payload() -> None:
    for rel, encoded in PAYLOAD.items():
        target = PROJECT / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        raw = gzip.decompress(base64.b64decode(encoded.encode("ascii")))
        target.write_bytes(raw)


def verify_python() -> None:
    for rel in [
        "app/report_input_models.py",
        "app/routers/report_inputs.py",
        "app/pcgd_xmc_report_builders_v1.py",
        "app/structured_report_catalog.py",
    ]:
        subprocess.run(
            [sys.executable, "-m", "py_compile", str(PROJECT / rel)],
            cwd=PROJECT,
            check=True,
        )


def verify_jinja() -> None:
    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    for name in [
        "partials/dropdown_menu_v1.html",
        "report_inputs/structured_school_form.html",
        "report_inputs/gv_mn01.html",
        "report_inputs/csvc_mn01.html",
    ]:
        env.get_template(name)


def create_table() -> None:
    code = (
        "from app.database import Base, engine\n"
        "import app.models, app.staff_models, app.report_input_models\n"
        "Base.metadata.create_all(bind=engine)\n"
        "print('CREATE_TABLES_OK')\n"
    )
    result = subprocess.run(
        [sys.executable, "-c", code],
        cwd=PROJECT,
        capture_output=True,
        text=True,
        check=True,
    )
    if "CREATE_TABLES_OK" not in result.stdout:
        raise RuntimeError("Chưa xác nhận tạo bảng dữ liệu chuyên biệt.")


def verify_db() -> None:
    if not DB.exists():
        raise RuntimeError(f"Không tìm thấy database: {DB}")
    con = sqlite3.connect(DB)
    try:
        row = con.execute(
            "SELECT name FROM sqlite_master "
            "WHERE type='table' AND name='school_structured_report_inputs'"
        ).fetchone()
    finally:
        con.close()
    if not row:
        raise RuntimeError("Không tìm thấy bảng school_structured_report_inputs.")


def verify_new_files() -> None:
    for rel, markers in NEW_MARKERS.items():
        text = read_text(rel)
        for marker in markers:
            if marker not in text:
                raise RuntimeError(f"Kiểm tra sau cài đặt không đạt: {rel} / {marker}")


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


